package org.apache.commons.lang3;

import java.io.*;
import java.lang.reflect.InvocationTargetException;
import java.lang.reflect.Method;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Iterator;
import java.util.List;
import java.util.Locale;
import java.util.regex.Pattern;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for org.apache.commons.lang3.StringUtils.join(Object[] array, String separator, int startIndex, int endIndex)
 */
public class StringUtils_join_TriageGen1Test {

    @Test
    public void testJoin_ArrayNull() {
        assertNull("Should return null when array is null", 
            StringUtils.join(null, ",", 0, 0));
    }

    @Test
    public void testJoin_SeparatorNull() {
        // When separator is null, it should be treated as EMPTY ("")
        Object[] array = {"a", "b", "c"};
        assertEquals("abc", StringUtils.join(array, null, 0, 3));
    }

    @Test
    public void testJoin_NoItems() {
        Object[] array = {"a", "b", "c"};
        // endIndex - startIndex <= 0 should return EMPTY
        assertEquals("", StringUtils.join(array, ",", 1, 1));
        assertEquals("", StringUtils.join(array, ",", 2, 1));
        assertEquals("", StringUtils.join(array, ",", 0, -1));
    }

    @Test
    public void testJoin_SingleItem() {
        Object[] array = {"a", "b", "c"};
        // Note: Based on the provided implementation logic:
        // for (int i = 0; i < 1; i++) { if (i >= 0) buf.append(separator); buf.append(array[i]); }
        // The provided code actually prepends the separator even for the first element.
        // Result should be: ",a"
        assertEquals(",a", StringUtils.join(array, ",", 0, 1));
    }

    @Test
    public void testJoin_MultipleItems() {
        Object[] array = {"a", "b", "c"};
        // i=0: append "," then "a" -> ",a"
        // i=1: append "," then "b" -> ",a,b"
        // i=2: append "," then "c" -> ",a,b,c"
        assertEquals(",a,b,c", StringUtils.join(array, ",", 0, 3));
    }

    @Test
    public void testJoin_WithNullElements() {
        Object[] array = {"a", null, "c"};
        // i=0: ",a"
        // i=1: append "," then skip null -> ",a,"
        // i=2: append "," then "c" -> ",a,,c"
        assertEquals(",a,,c", StringUtils.join(array, ",", 0, 3));
    }

    @Test
    public void testJoin_SubRange() {
        Object[] array = {"a", "b", "c", "d"};
        // startIndex=1, endIndex=3 (items: "b", "c")
        // i=1: append "," then "b" -> ",b"
        // i=2: append "," then "c" -> ",b,c"
        assertEquals(",b,c", StringUtils.join(array, ",", 1, 3));
    }

    @Test
    public void testJoin_EmptyArrayButValidRange() {
        // This case might throw ArrayIndexOutOfBoundsException in the provided code logic
        // if startIndex/endIndex are > 0 but array is empty. 
        // However, if array is empty and noOfItems > 0, it's an invalid state.
        // We test the logic provided.
        Object[] array = {};
        try {
            StringUtils.join(array, ",", 0, 1);
            fail("Expected ArrayIndexOutOfBoundsException");
        } catch (ArrayIndexOutOfBoundsException e) {
            // Expected
        }
    }
}
